export const ECC_LEVELS: HierarchyLevel[] = [
  { id: "lv-1", en: "Main domain", ar: "المكون الأساسي", pattern: "#", assessed: "rollup" },
  { id: "lv-2", en: "Subdomain", ar: "المكون الفرعي", pattern: "#-#", assessed: "rollup" },
  { id: "lv-3", en: "Control", ar: "الضابط", pattern: "#-#-#", assessed: "accepted" },
  { id: "lv-4", en: "Subcontrol", ar: "الضابط الفرعي", pattern: "#-#-#-#", assessed: "ai_reviewer" },
];

/** Domains and subdomains carry a name and an objective; controls and subcontrols carry their clause as the title. */
export const ECC_REQUIREMENTS: FrameworkRequirement[] = ROWS.map(([code, en, ar, textEn, textAr, note]) => {
  const depth = code.split("-").length;
  const r: FrameworkRequirement = { code, level: `lv-${depth}`, title: en, titleAr: ar };
  if (depth > 1) r.parent = code.slice(0, code.lastIndexOf("-"));
  if (textEn) r.text = textEn;
  if (textAr) r.textAr = textAr;
  r.source = note ? `ECC-2:2024 · ${note}` : "ECC-2:2024";
  return r;
});
